const raw = $input.first().json;
const body = raw.body ?? raw;

const audioBase64 = body.audioBase64 || body.audio_base64;
const mimeType = body.mimeType || body.mime_type || 'audio/webm';
const duration_sec = body.duration_sec ?? body.durationSec ?? null;
const source = body.source || 'mobile-voice-recorder';

if (!audioBase64 || typeof audioBase64 !== 'string') {
  throw new Error('Missing audioBase64. Use voice-recorder.html or POST { audioBase64, mimeType }');
}

// Get key once: docker exec leadspark-whisper whisper_manage --showkey
const WHISPER_API_KEY = 'PASTE_WHISPER_API_KEY';
if (!WHISPER_API_KEY || WHISPER_API_KEY === 'PASTE_WHISPER_API_KEY') {
  throw new Error('Set WHISPER_API_KEY in this Code node (docker exec leadspark-whisper whisper_manage --showkey)');
}

const whisperUrl = 'http://leadspark-whisper:9000/v1/audio/transcriptions';
const buf = Buffer.from(audioBase64, 'base64');

let ext = 'webm';
if (String(mimeType).includes('mp4')) ext = 'mp4';
if (String(mimeType).includes('wav')) ext = 'wav';
if (String(mimeType).includes('mpeg')) ext = 'mp3';

const form = new FormData();
form.append('file', new Blob([buf], { type: mimeType }), `audio.${ext}`);
form.append('model', 'whisper-1');

const res = await fetch(whisperUrl, {
  method: 'POST',
  headers: {
    Authorization: `Bearer ${WHISPER_API_KEY}`,
  },
  body: form,
});

if (!res.ok) {
  const errText = await res.text();
  throw new Error(`Whisper failed (${res.status}): ${errText}`);
}

const data = await res.json();
const transcript = String(data.text || '').trim();

return [{
  json: {
    ok: true,
    sheet_saved: false,
    transcript,
    summary: transcript ? `Call recorded (${duration_sec ?? '?'} sec). Transcript ready.` : '',
    language_detected: data.language || 'auto',
    duration_sec,
    source,
    fields: {
      name: null,
      phone: null,
      budget_min: null,
      budget_max: null,
      locality: null,
      timeline: null,
      purpose: null,
      bhk: null,
      lead_score: 'cold',
      notes: 'Local Whisper transcription only (no AI summary yet)',
    },
  },
}];
